import os, re
root = "/app"
skip = {"node_modules", "tmp", "log", "vendor", ".git", "public", "db/migrate"}
pat = re.compile(r'(?<![:\w])Proposal\b')
for dirpath, dirnames, filenames in os.walk(root):
    dirnames[:] = [d for d in dirnames if d not in {"node_modules","tmp","log","vendor",".git","public"} and not d.startswith(".")]
    rel_dir = os.path.relpath(dirpath, root)
    if rel_dir.startswith("db/migrate") or rel_dir.startswith("spec"):
        continue
    for fn in filenames:
        if not fn.endswith((".rb", ".erb", ".rake", ".js")):
            continue
        path = os.path.join(dirpath, fn)
        rel = os.path.relpath(path, root)
        text = open(path, errors="ignore").read()
        # strip Legislation::Proposal
        stripped = text.replace("Legislation::Proposal", "")
        if pat.search(stripped) or "ProposalNotification" in stripped or "proposals_path" in stripped or "admin_proposals_path" in stripped or "management_proposals_path" in stripped or "moderation_proposals_path" in stripped:
            hits = []
            for i,line in enumerate(stripped.splitlines(),1):
                if pat.search(line) or "ProposalNotification" in line or "proposals_path" in line or "admin_proposals_path" in line or "management_proposal" in line or "moderation_proposal" in line or "ProposalsController" in line:
                    hits.append(f"  {i}: {line.strip()[:160]}")
            if hits:
                print(rel)
                print("\n".join(hits[:12]))
                print()
