from pathlib import Path

def is_drop_header(line):
    protected = line.replace("legislation_proposal", "X").replace("Legislation::Proposal", "X")
    low = protected.lower()
    return ("proposal" in low) or ("Dashboard::" in line) or ("dashboard_administrator_task" in line)

def clean(path):
    lines = Path(path).read_text().splitlines(keepends=True)
    out = []
    skip_stack = []  # indents of dropped blocks
    for line in lines:
        stripped = line.strip()
        indent = len(line) - len(line.lstrip(" "))
        if skip_stack:
            if indent > skip_stack[-1]:
                continue
            if indent == skip_stack[-1] and stripped == "end":
                skip_stack.pop()
                continue
            if indent == skip_stack[-1] and stripped == "":
                continue
            # dedented past the block without end? stop skipping
            if indent < skip_stack[-1]:
                while skip_stack and indent <= skip_stack[-1]:
                    skip_stack.pop()
        if is_drop_header(line) and stripped.startswith(("describe ", "context ", "it ", "let(", "let ", "before ")):
            if stripped.startswith(("describe ", "context ")):
                skip_stack.append(indent)
            continue
        # drop leftover it/let lines mentioning proposal even if header check missed
        protected = line.replace("legislation_proposal", "X").replace("Legislation::Proposal", "X")
        if "proposal" in protected.lower() and stripped.startswith(("it ", "let(", "let ", "before ")):
            continue
        out.append(line)
    text = "".join(out)
    Path(path).write_text(text)
    print(path, "skip leftover", skip_stack)

